"""The raw tables the dbt project reads, as one list that both warehouses are built from (Postgres and BigQuery).

Three sources: `hub` (the hub's own daily figures, copied from the CSV files in powerbi/data that were written from its Postgres tables),
`shop` (order lines, refunds, products and customers; INVENTED, see generate_raw.py) and `ads` (campaign rows; INVENTED).
Types are the neutral names text, bigint, date, timestamp, bool; load_warehouse.py maps them to each warehouse's own names.
"""
TABLES = {
    # hub: copied from the hub's tables (column names kept; tenant_id dropped because the sample has one tenant)
    "metric_snapshot": [("connection_id", "text"), ("metric_key", "text"), ("observed_on", "date"), ("value_numeric", "bigint"), ("currency", "text"), ("synced_at", "timestamp")],
    "metric": [("metric_key", "text"), ("label", "text"), ("unit", "text"), ("kind", "text")],
    "platform_connection": [("connection_id", "text"), ("platform", "text"), ("display_name", "text"), ("external_account", "text")],
    "sync_run": [("connection_id", "text"), ("trigger", "text"), ("window_start", "date"), ("window_end", "date"), ("status", "text"), ("rows_written", "bigint"),
                 ("error_code", "text"), ("started_at", "timestamp"), ("finished_at", "timestamp")],
    # shop: invented order level rows whose daily totals equal the hub's daily figures
    "orders": [("order_id", "text"), ("customer_id", "text"), ("placed_at", "timestamp"), ("currency", "text"), ("financial_status", "text"), ("channel", "text"), ("_loaded_at", "timestamp")],
    "order_lines": [("order_line_id", "text"), ("order_id", "text"), ("product_id", "text"), ("quantity", "bigint"), ("unit_price_cents", "bigint")],
    "refunds": [("refund_id", "text"), ("order_id", "text"), ("refunded_at", "timestamp"), ("amount_cents", "bigint"), ("reason", "text")],
    "products": [("product_id", "text"), ("product_name", "text"), ("category", "text"), ("list_price_cents", "bigint"), ("active", "bool")],
    "customers": [("customer_id", "text"), ("created_at", "timestamp"), ("country", "text"), ("acquisition_channel", "text")],
    # ads: invented campaign rows whose daily totals equal the hub's ad account figures
    "ads_campaign_daily": [("account_id", "text"), ("campaign_id", "text"), ("campaign_name", "text"), ("report_date", "date"), ("spend_cents", "bigint"), ("impressions", "bigint"),
                           ("clicks", "bigint"), ("purchases", "bigint"), ("purchase_value_cents", "bigint"), ("currency", "text"), ("_loaded_at", "timestamp")],
}

# tables copied from the hub's CSV export versus tables generated by generate_raw.py
HUB_TABLES = ("metric_snapshot", "metric", "platform_connection", "sync_run")
